import sys

def solve():
    input = sys.stdin.read().split()
    if not input:
        return

    iterator = iter(input)

    try:
        N = int(next(iterator))
        M = int(next(iterator))

        students = []
        for _ in range(N):
            a = int(next(iterator))
            b = int(next(iterator))
            students.append((a, b))

        checkpoints = []
        for j in range(1, M + 1):
            c = int(next(iterator))
            d = int(next(iterator))
            checkpoints.append((c, d, j))

        results = []
        for sx, sy in students:
            min_dist = float('inf')
            best_j = -1

            for j, (cx, cy, idx) in enumerate(checkpoints):
                dist = abs(sx - cx) + abs(sy - cy)
                if dist < min_dist:
                    min_dist = dist
                    best_j = idx

            results.append(best_j)

        for res in results:
            print(res)

    except StopIteration:
        pass

if __name__ == "__main__":
    solve()
